CREATE TABLE IF NOT EXISTS usuarios(id INTEGER PRIMARY KEY AUTOINCREMENT,correo TEXT UNIQUE NOT NULL,nombre TEXT NOT NULL,rol TEXT NOT NULL CHECK(rol IN('comision','estudiante','docente')));
CREATE TABLE IF NOT EXISTS torneos(id INTEGER PRIMARY KEY AUTOINCREMENT,nombre TEXT,anio INTEGER NOT NULL,fecha_inicio TEXT NOT NULL,fecha_fin TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'en_proceso' CHECK(estado IN('en_proceso','terminado')));
CREATE TABLE IF NOT EXISTS grupos(id INTEGER PRIMARY KEY AUTOINCREMENT,torneo_id INTEGER NOT NULL REFERENCES torneos(id) ON DELETE CASCADE,nombre TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS equipos(id INTEGER PRIMARY KEY AUTOINCREMENT,grupo_id INTEGER NOT NULL REFERENCES grupos(id) ON DELETE CASCADE,nombre TEXT NOT NULL,logo TEXT,entrenador TEXT);
CREATE TABLE IF NOT EXISTS jugadores(id INTEGER PRIMARY KEY AUTOINCREMENT,equipo_id INTEGER NOT NULL REFERENCES equipos(id) ON DELETE CASCADE,nombre TEXT NOT NULL,apellido TEXT NOT NULL,carnet TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS partidos(id INTEGER PRIMARY KEY AUTOINCREMENT,grupo_id INTEGER NOT NULL REFERENCES grupos(id) ON DELETE CASCADE,equipo_local_id INTEGER NOT NULL REFERENCES equipos(id) ON DELETE CASCADE,equipo_visitante_id INTEGER NOT NULL REFERENCES equipos(id) ON DELETE CASCADE,tecnico_local TEXT,tecnico_visitante TEXT,jornada INTEGER NOT NULL DEFAULT 1,fecha TEXT NOT NULL,hora TEXT,cancha TEXT,goles_local INTEGER,goles_visitante INTEGER,estado TEXT NOT NULL DEFAULT 'programado' CHECK(estado IN('programado','jugado','suspendido','reprogramado')));
CREATE TABLE IF NOT EXISTS estadisticas_partido(id INTEGER PRIMARY KEY AUTOINCREMENT,partido_id INTEGER NOT NULL REFERENCES partidos(id) ON DELETE CASCADE,jugador_id INTEGER NOT NULL REFERENCES jugadores(id) ON DELETE CASCADE,goles INTEGER DEFAULT 0,asistencias INTEGER DEFAULT 0,autogoles INTEGER DEFAULT 0,amarillas INTEGER DEFAULT 0,rojas INTEGER DEFAULT 0,faltas_cometidas INTEGER DEFAULT 0,faltas_recibidas INTEGER DEFAULT 0,tiros INTEGER DEFAULT 0,tiros_arco INTEGER DEFAULT 0,pases_intentados INTEGER DEFAULT 0,atajadas INTEGER DEFAULT 0,UNIQUE(partido_id,jugador_id));
CREATE TABLE IF NOT EXISTS sanciones(id INTEGER PRIMARY KEY AUTOINCREMENT,jugador_id INTEGER NOT NULL REFERENCES jugadores(id) ON DELETE CASCADE,partido_origen_id INTEGER REFERENCES partidos(id) ON DELETE CASCADE,tipo TEXT NOT NULL CHECK(tipo IN('amarillas','roja','agresion')),partidos_suspendido INTEGER NOT NULL,partidos_cumplidos INTEGER NOT NULL DEFAULT 0,activa INTEGER NOT NULL DEFAULT 1,quitada_por INTEGER REFERENCES usuarios(id));
